from pathlib import Path

path = Path("Sources/Views/V2MatchExperience.swift")
s = path.read_text()

old = '''    private var lineupsView: some View {\n        VStack(spacing: 12) {\n            if store.lineups.isEmpty && store.progress.mayShowEmpty(.lineups) { unavailable("التشكيلة غير منشورة حاليًا") }\n            ForEach(Array(store.lineups.enumerated()), id: \\.offset) { _, lineup in\n                VStack(alignment: .leading, spacing: 12) {\n                    HStack {\n                        RemoteBadge(url: lineup.team.logo).frame(width: 40, height: 40)\n                        VStack(alignment: .leading, spacing: 2) {\n                            Text(SportsArabic.team(lineup.team.name ?? "فريق")).font(.headline)\n                            Text("الخطة \\(lineup.formation ?? "—")").font(.caption).foregroundStyle(AppTheme.green)\n                        }\n                        Spacer()\n                    }\n                    ForEach(Array((lineup.startXI ?? []).enumerated()), id: \\.offset) { _, slot in\n                        HStack(spacing: 10) {\n                            Text(slot.player.number.map(String.init) ?? "—")\n                                .font(.caption.bold()).foregroundStyle(AppTheme.green)\n                                .frame(width: 30, height: 30)\n                                .background(AppTheme.green.opacity(0.10), in: Circle())\n                            Text(slot.player.name ?? "لاعب").font(.subheadline.weight(.medium))\n                            Spacer()\n                            Text(positionText(slot.player.pos)).font(.caption).foregroundStyle(AppTheme.muted)\n                        }\n                    }\n                }\n                .padding(15)\n                .background(AppTheme.cardRaised, in: RoundedRectangle(cornerRadius: 20, style: .continuous))\n                .overlay(RoundedRectangle(cornerRadius: 20, style: .continuous).stroke(AppTheme.border, lineWidth: 1))\n            }\n        }.padding(.horizontal, 16)\n    }\n'''

new = '''    private var lineupsView: some View {\n        VStack(spacing: 14) {\n            if store.lineups.isEmpty && store.progress.mayShowEmpty(.lineups) { unavailable("التشكيلة غير منشورة حاليًا") }\n            ForEach(Array(store.lineups.enumerated()), id: \\.offset) { _, lineup in\n                VStack(alignment: .leading, spacing: 14) {\n                    HStack(spacing: 10) {\n                        RemoteBadge(url: lineup.team.logo).frame(width: 44, height: 44)\n                        VStack(alignment: .leading, spacing: 3) {\n                            Text(SportsArabic.team(lineup.team.name ?? "فريق")).font(.headline)\n                            HStack(spacing: 8) {\n                                Label(lineup.formation ?? "—", systemImage: "rectangle.split.3x3")\n                                Text("•")\n                                Text("\\((lineup.startXI ?? []).count) أساسي")\n                                Text("•")\n                                Text("\\((lineup.substitutes ?? []).count) بديل")\n                            }.font(.caption2).foregroundStyle(AppTheme.green)\n                        }\n                        Spacer()\n                    }\n                    if let coach = lineup.coach?.name, !coach.isEmpty {\n                        HStack(spacing: 9) {\n                            Image(systemName: "person.crop.circle.badge.checkmark").foregroundStyle(AppTheme.green)\n                            Text("المدرب").font(.caption).foregroundStyle(AppTheme.muted)\n                            Spacer()\n                            Text(coach).font(.subheadline.weight(.semibold))\n                        }\n                        Divider().overlay(AppTheme.border)\n                    }\n                    lineupSection("الأساسيون", players: lineup.startXI ?? [], icon: "figure.soccer")\n                    if let substitutes = lineup.substitutes, !substitutes.isEmpty {\n                        Divider().overlay(AppTheme.border)\n                        lineupSection("البدلاء", players: substitutes, icon: "person.2.fill")\n                    }\n                }\n                .padding(15)\n                .background(AppTheme.cardRaised, in: RoundedRectangle(cornerRadius: 20, style: .continuous))\n                .overlay(RoundedRectangle(cornerRadius: 20, style: .continuous).stroke(AppTheme.border, lineWidth: 1))\n            }\n        }.padding(.horizontal, 16)\n    }\n\n    @ViewBuilder private func lineupSection(_ title: String, players: [APILineupItem.Slot], icon: String) -> some View {\n        VStack(alignment: .leading, spacing: 9) {\n            Label(title, systemImage: icon)\n                .font(.caption.bold()).foregroundStyle(AppTheme.muted)\n            ForEach(Array(players.enumerated()), id: \\.offset) { _, slot in\n                HStack(spacing: 10) {\n                    Text(slot.player.number.map(String.init) ?? "—")\n                        .font(.caption.bold()).foregroundStyle(AppTheme.green)\n                        .frame(width: 30, height: 30)\n                        .background(AppTheme.green.opacity(0.10), in: Circle())\n                    Text(slot.player.name ?? "لاعب").font(.subheadline.weight(.medium)).lineLimit(1)\n                    Spacer(minLength: 6)\n                    Text(positionText(slot.player.pos)).font(.caption).foregroundStyle(AppTheme.muted)\n                }\n            }\n        }\n    }\n'''

if new in s:
    print("Lineup UI fixes already applied")
elif old in s:
    s = s.replace(old, new, 1)
    path.write_text(s)
    print("Applied complete lineup UI: starters, substitutes, formation and coach")
else:
    raise SystemExit("lineup UI patch pattern missing")
